<?php
require_once '../config.php';require_once '../includes/auth.php';require_admin();$error='';$event=['title'=>'','category'=>'','description'=>'','event_date'=>'','event_time'=>'','venue'=>'','capacity'=>100];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($event as $k=>$v){$event[$k]=trim((string)($_POST[$k]??$v));}$event['capacity']=(int)$event['capacity'];if(in_array('',[$event['title'],$event['category'],$event['description'],$event['event_date'],$event['event_time'],$event['venue']],true)||$event['capacity']<1||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$event['event_date']))$error='Complete all fields with valid values.';else{try{$s=$conn->prepare('INSERT INTO events(title,category,description,event_date,event_time,venue,capacity) VALUES(?,?,?,?,?,?,?)');$s->bind_param('ssssssi',$event['title'],$event['category'],$event['description'],$event['event_date'],$event['event_time'],$event['venue'],$event['capacity']);$s->execute();set_flash('success','Event created successfully.');redirect('dashboard.php');}catch(Throwable $e){error_log($e->getMessage());$error='Unable to create the event.';}}}
$page_title='Add Event';$asset_prefix='../';include '../includes/header.php'; ?>
<main class="page-shell"><div class="form-page"><div><p class="eyebrow">EVENT CONFIGURATION</p><h1>Create an event</h1><p>Create a clear event listing students can understand and register for.</p></div><?php if($error): ?><div class="alert error"><?= h($error) ?></div><?php endif; ?><form method="post" class="form form-card"><?= csrf_field() ?><label>Event Title<input name="title" maxlength="150" value="<?= h($event['title']) ?>" required></label><div class="form-row"><label>Category<input name="category" maxlength="80" value="<?= h($event['category']) ?>" required></label><label>Capacity<input type="number" min="1" name="capacity" value="<?= (int)$event['capacity'] ?>" required></label></div><label>Description<textarea name="description" rows="5" required><?= h($event['description']) ?></textarea></label><div class="form-row"><label>Date<input type="date" name="event_date" value="<?= h($event['event_date']) ?>" required></label><label>Time<input type="time" name="event_time" value="<?= h($event['event_time']) ?>" required></label></div><label>Venue<input name="venue" maxlength="150" value="<?= h($event['venue']) ?>" required></label><button class="primary-btn" type="submit">Publish Event</button></form></div></main><?php include '../includes/footer.php'; ?>
